  if (expectedChecksum !== undefined && expectedChecksum !== sumCents) {
    return { ok: false, errorCode: ERR_BATCH_CHECKSUM_704, entries: [] };
  }
  return { ok: true, errorCode: null, entries, sumCents };
}

